// lalrMakeSequence wraps a list of action nodes into a single And node (sequence).
func lalrMakeSequence(stmts []ast.Node) ast.Node {
	if len(stmts) == 0 {
		return &ast.And{}
	}
	if len(stmts) == 1 {
		return stmts[0]
	}
	return &ast.And{Terms: stmts}
}

